        nodes[a].link.append(nodes[b])
        nodes[b].link.append(nodes[a])

    starts = [u, v]
    for i in range(2):
        clear_nodes(nodes)
        q = deque()
        q.append((nodes[starts[i]], 0))
        while len(q) > 0:
            node, cost = q.popleft()
            node.costs[i] = cost
            for next_node in node.link:
                if not next_node.check:
                    q.append((next_node, cost + 1))
                    next_node.check = True

    if nodes[u].costs[1] == 1:
        print(0)
        return

    clear_nodes(nodes)
