class Stack:
    def __init__(self, data=None):
        # Pythonではクラスのデフォルト引数は１度しか初期化されないため、
        # うっかりdata=[]としてしまうと、複数のインスタンスを生成したときに
        # 同じ配列を参照することになってしまう！！！
        # http://amacbee.hatenablog.com/entry/2016/12/07/004510
        if data is None:
            self.data = []
        else:
            self.data = data

    def push(self, x):
        self.data.append(x)

    def pop(self):
        if self.is_empty() is True:
            return None
        else:
            return self.data.pop(-1)

    def is_empty(self):
        if len(self.data) == 0:
            return True
        else:
            return False

    def get_length(self):
        return len(self.data)

    def reverse(self):
        self.data.reverse()


