import bisect

def nearest(x, lst):
    p = bisect.bisect_left(lst, x)

    if p == 0:
        return lst[p], None
    if p == len(lst):
        return lst[p - 1], None
    if lst[p] == x:
        return lst[p], None
    return lst[p - 1], lst[p]


