    for i in range(n-k+1):
        # print(i, -1-i, f" --- {a[i]}, {a[-i-1]}, {lll[-i-1]}")
        ans = (ans + (a[-i-1] - a[i]) * lll[-i-1]) % mod
    print(ans)

