def dist(i, j, X, Y):
    if j <= X:
        return j - i
    if i >= Y:
        return j - i
    if i <= X < Y <= j:
        return X - i + 1 + j - Y
    if X <= i < j <= Y:
        d1 = j - i
        d2 = i - X + 1 + Y - j
        return min(d1, d2)
    if i <= X <= j <= Y:
        d1 = j - i
        d2 = X - i + 1 + Y - j
        return min(d1, d2)
    else:
        d1 = j - i
        d2 = i - X + 1 + j - Y
        return min(d1, d2)


