    def solve(n,x):
        # print(n,x)
        if n == 0: return 1
        c = 2**(n+2)-3
        half = c//2

        res = 0
        if x <= half:
            if x == 1:
                res += 0
            else:
                res += solve(n-1,x-1)
        elif x == half+1:
            res += 2**(n-1+1) - 1 + 1
        elif x < c:
            res += 2**(n-1+1) - 1 + 1 + solve(n-1,x-(half+1))
        else:
            assert x == c
            res += 2**(n+1)-1

        return res

