    res = 0
    S = set()
    for k in range(N):
        for i in range(N):
            for j in range(N):
                # 3頂点が異なってかつ、経由のが近い場合は直接の辺は不要
                if i != j and j != k and k != i \
                        and G[i][k] + G[k][j] == G[i][j]:
                    if (i, j) not in S:
                        S.add((i, j))
                        res += G[i][j]
    return res

