@njit(i8[:, :](i8, i8, i8[:, :], i8[:, :]), cache=True)
def calc_cost(N, C, D, c):
    cost = np.zeros((C, 3), dtype=np.int64)
    for i in range(N):
        for j in range(N):
            for k in range(C):
                cost[k][(i + j) % 3] += D[c[i][j] - 1][k]
    return cost


