class UfNode():
    def __init__(self, id):
        self.parent = None
        self.id = id
        self._size = 1

    @property
    def size(self):
        if not self.parent:
            return self._size
        else:
            return self.root()._size

    def root(self):
        if not self.parent:
            return self
        else:
            return self.parent.root()

    def sizeup(self, n):
        if not self.parent:
            self._size += n
        else:
            self.root().sizeup(n)

    def unite(self, target):
        sr = self.root().id
        tr = target.root().id
        if sr == tr:
            return False
        elif sr > tr:
            target.sizeup(self.size)
            self.root().parent = target.root()
        else:
            self.sizeup(target.size)
            target.root().parent = self.root()


def solve():
