        c1 = nodes[a].size
        c2 = nodes[b].size
        nodes[b].unite(nodes[a])
        if c2 != nodes[b].size:
            cur += c1*c2
        benlist.append(cur)

    t = benlist.pop()
    benlist.reverse()
    #print(benlist)

    ans = [t - i for i in benlist]
    split_print_enter(ans)




